% Define variables
x = 0.85;
y = 12.5;

% Create column vector with required elements
v = [sin(80*y);   % element 1: sin(80y)
     y^x;         % element 2: y raised to power x
     log(x);      % element 3: natural log of x
     x*y;         % element 4: x times y
     sqrt(x+y)];  % element 5: square root of (x+y)

disp('Column vector v:');
disp(v);

% SVD Decomposition
A = [4 3; 6 3; 2 1];  % example matrix

% Full SVD
[U, S, V] = svd(A);         % full SVD
A_reconstructed = U * S * V'; % reconstruct A
fprintf('SVD reconstruction error: %e\n', norm(A - A_reconstructed));

% Thin (Economy) SVD
[U2, S2, V2] = svd(A, 'econ');  % economy SVD

% PLU Decomposition
B = [2 1 1; 4 3 3; 8 7 9];  % square matrix for LU
[L, U, P] = lu(B);           % LU with pivoting: P*B = L*U
B_reconstructed = P' * L * U; % reconstruct original B
fprintf('PLU reconstruction error: %e\n', norm(B - B_reconstructed));

disp('L matrix:'); disp(L);
disp('U matrix:'); disp(U);
disp('P matrix:'); disp(P);

% Create a 4x4 random matrix
A = rand(4);                  % generate random 4x4 matrix
fprintf('Random Matrix A:\n');
disp(A);

% Find eigenvalues and eigenvectors
[V, D] = eig(A);              % V: eigenvectors, D: eigenvalue diagonal matrix
fprintf('Eigenvalues (diagonal of D):\n');
disp(diag(D));                % display eigenvalues
fprintf('Eigenvectors (columns of V):\n');
disp(V);

% Check linear independence
r = rank(V);                  % compute rank of eigenvector matrix
fprintf('Rank of eigenvector matrix: %d\n', r);

if r == 4
    fprintf('Eigenvectors are linearly independent and SPAN R4.\n');
else
    fprintf('Eigenvectors are NOT linearly independent.\n');
end

% Also check determinant
d = det(V);
fprintf('det(V) = %.6f\n', d);
if abs(d) > 1e-10
    fprintf('det(V) != 0: confirms linear independence.\n');
end

